create or replace TABLE SZD_PRODUCTION.ETL.T_ETL_CHARGER_CHARGERS_B (
	RESOURCE_ITEM_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the resource item.',
	DWH_VALID_FROM_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record became valid.',
	DWH_VALID_TO_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was no longer valid.',
	DWH_VALID_FG BOOLEAN NOT NULL COMMENT 'An indicator showing the current record in history.',
	CHARGER_UUID_NR VARCHAR(250) NOT NULL COMMENT 'Natural/Business Key - Technical key of the charger.',
	CHARGER_PROVIDER_SYSTEM_CD VARCHAR(50) NOT NULL COMMENT 'The unique code of the charger provider system.',
	CHARGER_MODEL_RESOURCE_ITEM_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the resource item.',
	REAL_ESTATE_RESOURCE_ITEM_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the resource item.',
	CHARGER_COMMUNICATION_STATUS_ID NUMBER(38,0) NOT NULL COMMENT 'The unique ID of the communication status of a charger.',
	CHARGER_COMMUNICATION_TYPE_ID NUMBER(38,0) NOT NULL COMMENT 'The unique code of the communication type of a charger.',
	CHARGING_STATION_OWNER_PARTY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the charging station owner.',
	CHARGER_DLSOFTWARE_NR NUMBER(38,0) NOT NULL COMMENT 'Descriptive Attribute - Technical key of the DL software',
	CHARGER_ELS_NR VARCHAR(250) NOT NULL COMMENT 'Descriptive Attribute - Technical key of ELS (ELS = Elektronische Ladesäule)',
	LABEL_NR VARCHAR(250) NOT NULL COMMENT 'The label of the charger containing informations about the division and the associated real estate.',
	PUBLIC_DISPLAY_NAME VARCHAR(100) COMMENT 'Descriptive Attribute -  The public display name of the charger.',
	MAX_CHARGE_POWER_MEAS NUMBER(38,5) COMMENT 'The maximum power of the charger in kW.',
	SERIAL_NR VARCHAR(250) COMMENT 'Descriptive Attribute - The serial number of the charger.',
	FIRMWARE_VERSION_TXT VARCHAR(1000) COMMENT 'Descriptive Attribute - The firmware version used in the charger',
	ANALYTIC_ACCOUNT_TXT VARCHAR(1000) COMMENT 'Descriptive Attribute - The company used for analysis ',
	IMSI_NR VARCHAR(250) COMMENT 'Descriptive Attribute - International Mobile Subscriber Identity',
	ICC_NR VARCHAR(250) COMMENT 'Descriptive Attribute - ICC ID of the charger.',
	METER_TYPE_NR VARCHAR(250) COMMENT 'Descriptive Attribute - The number of the meter type.',
	METER_SERIAL_NR VARCHAR(250) COMMENT 'Descriptive Attribute - The serial number of the meter.',
	LAST_HEARTBEAT_TMSP TIMESTAMP_TZ(9) COMMENT 'Descriptive Attribute - Timestamp of the last heartbeat of the charger',
	HEARTBEAT_INTERVAL_SEC NUMBER(38,0) COMMENT 'Descriptive Attribute - The interval of the heartbeat in seconds.',
	IP_ADDRESS_NR VARCHAR(250) COMMENT 'Descriptive Attribute - The IP address of the charger',
	CREATED_AT_TMSP TIMESTAMP_TZ(9) COMMENT 'Descriptive Attribute - Technical timestamp when this record was created in the source',
	UPDATED_AT_TMSP TIMESTAMP_TZ(9) COMMENT 'Descriptive Attribute - Technical timestamp when this record was updated in the source',
	INSTALLATION_DT DATE COMMENT 'Descriptive Attribute - The date of installation of the charger',
	COMMISSIOING_DT DATE COMMENT 'Descriptive Attribute - The date of commissioning the charger',
	CPO_OPERATION_COST_RATE_VAL NUMBER(38,5) COMMENT 'Descriptive Attribute - Operations cost rate of the CPO.',
	SIT_INTERNAL_IP_ADDRESS_NR VARCHAR(250) COMMENT 'Descriptive Attribute - SIT internal IP address',
	OPERATOR_NAME VARCHAR(100) NOT NULL COMMENT 'Descriptive Attribute - Name of the operator of the charger (usually a country organisation).',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was inserted into the table.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was last modified. (In case the record has not been modified since its creation, dwh_updated is identical to dwh_created.)',
	DWH_SRC_FILE_NAME VARCHAR(500) COMMENT 'Contains the name(s) of the input file(s) that delivered the record. It can be either the full path of the BLOG storage or the shortened file path',
	DWH_SRC_1_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The extraction timestamp of the record from the source',
	constraint PK_CHARGER primary key (RESOURCE_ITEM_SID, DWH_VALID_FROM_TMSP)
);